export async function listTools() {
  return [
    {
      name: 'run_with_progress',
      description: 'Run a task and report progress from 0 to 1',
      inputSchema: {
        type: 'object',
        properties: {
          steps: {
            type: 'integer',
            minimum: 1,
            description: 'Number of steps (positive integer)'
          }
        },
        required: ['steps'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}, ctx = {}) {
  if (name !== 'run_with_progress') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32601;
    throw err;
  }
  const steps = args.steps;
  if (!Number.isInteger(steps) || steps < 1) {
    const err = new Error('steps must be a positive integer');
    err.code = -32602;
    throw err;
  }
  const onProgress = (ctx && typeof ctx.onProgress === 'function') ? ctx.onProgress : null;
  if (onProgress) onProgress(0);
  for (let i = 1; i <= steps; i++) {
    await Promise.resolve();
    if (onProgress) onProgress(i / steps);
  }
  return {
    content: [{ type: 'text', text: 'completed' }]
  };
}
```

